        f'{content}</td></tr></table>'
    )


def md_to_html(md_text, footer_img_url="", footer_desc=""):
    lines = md_text.split("\n")
    out = []
    i = 0
    n = len(lines)

    while i < n:
        s = lines[i].strip()
        if not s:
            i += 1; continue

        # Blockquote
        if s.startswith("> "):
            quotes = []
            while i < n and lines[i].strip().startswith("> "):
                quotes.append(lines[i].strip()[2:])
                i += 1
            text = "<br>".join(quotes)
            out.append(make_blockquote(text))
            continue

